-- One SELECT policy per table; admin writes remain separate from staff reads.
drop policy admin_write on public.webbase_network_imports;
create policy admin_insert on public.webbase_network_imports for insert to authenticated with check ((select private.webbase_is_admin()));
create policy admin_update on public.webbase_network_imports for update to authenticated using ((select private.webbase_is_admin())) with check ((select private.webbase_is_admin()));
create policy admin_delete on public.webbase_network_imports for delete to authenticated using ((select private.webbase_is_admin()));
